        public void SetCursor(GlfwCursor cursor) => Glfw.PInvoke.SetCursor(this, cursor);

        /// <summary>
        ///   Makes the context of the specified window current for the calling thread.
        /// </summary>
        /// <remarks>
        ///   This function makes the OpenGL or OpenGL ES context of the specified window current on the calling thread.
        ///   It can also detach the current context from the calling thread without making a new one current by passing
        ///   in <c>null</c>.
        ///   <para>
        ///     A context must only be made current on a single thread at a time and each thread can have only a single
        ///     current context at a time. Making a context current detaches any previously current context on the
        ///     calling thread.
        ///   </para>
        ///   <para>
        ///     When moving a context between threads, you must detach it (make it non-current) on the old thread before
        ///     making it current on the new one.
        ///   </para>
        ///   <para>
        ///     By default, making a context non-current implicitly forces a pipeline flush. On machines that support
        ///     <c>GL_KHR_context_flush_control</c>, you can control whether a context performs this flush by setting
        ///     the GLFW_CONTEXT_RELEASE_BEHAVIOR hint.
        ///   </para>
        ///   <para>
        ///     The specified window must have an OpenGL or OpenGL ES context. Specifying a window without a context
        ///     will generate a <see cref="GlfwErrorCode.NoCurrentContext"/> error.
        ///   </para>
        ///   <para>
        ///     If the previously current context was created via a different context creation API than the one passed
        ///     to this function, GLFW will still detach the previous one from its API before making the new one
        ///     current.
        ///   </para>
        /// </remarks>
        /// <possibleErrors>
        ///   <see cref="GlfwErrorCode.NotInitialized"/>, <see cref="GlfwErrorCode.NoWindowContext"/>,
        ///   <see cref="GlfwErrorCode.PlatformError"/>
        /// </possibleErrors>
        /// <threadSafety>
        ///   This function may be called from any thread.
        /// </threadSafety>
        /// <seealso href="https://www.glfw.org/docs/latest/context_guide.html#context_current">Current
        ///   context</seealso>
        public void MakeContextCurrent() => Glfw.PInvoke.MakeContextCurrent(this);

        /// <summary>
        ///   Swaps the front and back buffers of the window
        /// </summary>
        /// <remarks>
        ///   This function swaps the front and back buffers of the window when rendering with OpenGL or OpenGL ES. If
        ///   the swap interval is greater than zero, the GPU driver waits the specified number of screen updates before
        ///   swapping the buffers.
        ///   <para>
        ///     The window must have an OpenGL or OpenGL ES context. Specifying a window without a context will generate
        ///     a <see cref="GlfwErrorCode.NoWindowContext"/> error.
        ///   </para>
        ///   <para>
        ///     This function does not apply to Vulkan.
        ///   </para>
        /// </remarks>
        /// <threadSafety>
        ///   This function may be called from any thread.
        /// </threadSafety>
        /// <possibleErrors>
        ///   <see cref="GlfwErrorCode.NotInitialized"/>, <see cref="GlfwErrorCode.NoWindowContext"/>,
        ///   <see cref="GlfwErrorCode.PlatformError"/>
        /// </possibleErrors>
        /// <seealso cref="Glfw.SwapInterval">GlfwWindow.SwapInterval</seealso>
        /// <seealso href="https://www.glfw.org/docs/latest/window_guide.html#buffer_swap">Buffer swapping</seealso>
        public void SwapBuffers() => Glfw.PInvoke.SwapBuffers(this);
    }
}
